/*
 * A014823  Inverse of 814th cyclotomic polynomial.
 * https://oeis.org/A014823
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, easy
 * Formula:   a(n) = coefficients of the inverse of the 814th cyclotomic
 *            polynomial. The sequence is periodic with period 814. The values
 *            are generated by the recurrence a(0) = 1 a(n) =
 *            -∑_{k=1}^{deg(Φ)} Φ_k · a(n-k) (n ≥ 1) where Φ_k are the
 *            coefficients of the cyclotomic polynomial Φ₈₁₄(x)
 * Range:     i8 n <= 1000, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   poly_div_ll
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include "../utils/poly_div_ll.h"

/* ---------- Polynomial arithmetic in long long (intermediate values) ---------- */

static void poly_mul_ll(const long long *a, size_t da,
                        const long long *b, size_t db,
                        long long *out, size_t *dout) {
    /* out has space for da+db+1 elements */
    for (size_t i = 0; i <= da + db; ++i) out[i] = 0;
    for (size_t i = 0; i <= da; ++i) {
        if (a[i] == 0) continue;
        for (size_t j = 0; j <= db; ++j) {
            out[i + j] += a[i] * b[j];
        }
    }
    size_t d = da + db;
    while (d > 0 && out[d] == 0) --d;
    *dout = d;
}

/* ---------- Compute Φ₈₁₄(x) and store its coefficients in Φ[0..360] ---------- */

static void compute_phi_814(seq_t *φ, size_t *deg_phi) {
    /* factors with μ(n/d) = +1 (numerator) and -1 (denominator) */
    const int num_factors[] = {2, 11, 37, 814};
    const int den_factors[] = {1, 22, 74, 407};
    const int nf = 4, df = 4;

    long long num[865] = {0}, den[865] = {0};
    size_t num_deg = 0, den_deg = 0;

    /* polynomial 1 */
    num[0]   = 1;          /* numerator starts as 1 */
    den[0]   = 1;          /* denominator starts as 1   */

    /* multiply numerator factors (x^d – 1) */
    for (int i = 0; i < nf; ++i) {
        size_t d = num_factors[i];
        long long fac[865] = {0};
        fac[0] = -1;       /* –1 at degree 0 */
        fac[d] =  1;       /* +1 at degree d   */
        long long tmp[865];
        poly_mul_ll(num, num_deg, fac, d, tmp, &num_deg);
        for (size_t j = 0; j <= num_deg; ++j) num[j] = tmp[j];
    }

    /* multiply denominator factors (x^d – 1) */
    for (int i = 0; i < df; ++i) {
        size_t d = den_factors[i];
        long long fac[865] = {0};
        fac[0] = -1;
        fac[d] =  1;
        long long tmp[865];
        poly_mul_ll(den, den_deg, fac, d, tmp, &den_deg);
        for (size_t j = 0; j <= den_deg; ++j) den[j] = tmp[j];
    }

    /* divide the two products to obtain Φ₈₁₄(x) */
    long long quo[865];
    size_t quo_deg;
    poly_div_ll(num, num_deg, den, den_deg, quo, &quo_deg);

    *deg_phi = quo_deg;
    for (size_t i = 0; i <= quo_deg; ++i) φ[i] = (seq_t)quo[i];
}

/* ---------- Sequence cache ------------------------------------------------- */

static int init_flag = 0;           /* 0 = not initialized, 1 = initialized   */
static seq_t cycle[814];            /* period 814 */

/* initialise the period values after computing Φ₈₁₄(x) */
static void init_cycle(void) {
    seq_t φ[865];
    size_t deg_phi;
    compute_phi_814(φ, &deg_phi);

    cycle[0] = 1;                   /* a(0) */
    for (idx_t n = 1; n < 814; ++n) {
        seq_t sum = 0;
        size_t maxk = (n < deg_phi) ? (size_t)n : deg_phi;
        for (size_t k = 1; k <= maxk; ++k) {
            sum += φ[k] * cycle[(size_t)(n - k)];
        }
        cycle[(size_t)n] = -sum;
    }
    init_flag = 1;
}

/* ---------- Required function --------------------------------------------- */

seq_t a(idx_t n) {
    if (!init_flag) init_cycle();
    return cycle[(size_t)(n % 814)];
}
